class Seau(int capacite, double parSeconde)
{
    double _jetons = capacite;
    double _dernier;
    public bool Prendre(double maintenant)
    {
        _jetons = Math.Min(capacite, _jetons
            + (maintenant - _dernier) * parSeconde);
        _dernier = maintenant;
        if (_jetons < 1) return false;
        _jetons--;
        return true;
    }
}

